-- 可重复执行：先 DROP 再 CREATE
-- ============================================================
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
CREATE DATABASE IF NOT EXISTS new_060 DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
USE new_060;

DROP TABLE IF EXISTS `course`;
DROP TABLE IF EXISTS `code_assignment`;
DROP TABLE IF EXISTS `code_submission`;
DROP TABLE IF EXISTS `code_submission_version`;
DROP TABLE IF EXISTS `peer_review_task`;
DROP TABLE IF EXISTS `peer_review_score`;
DROP TABLE IF EXISTS `similarity_record`;
DROP TABLE IF EXISTS `score_summary`;
DROP TABLE IF EXISTS `appeal_record`;
DROP TABLE IF EXISTS `credibility_rule`;
DROP TABLE IF EXISTS `credibility_snapshot`;
DROP TABLE IF EXISTS `sys_user`;
DROP TABLE IF EXISTS `sys_org`;
DROP TABLE IF EXISTS `sys_role`;
DROP TABLE IF EXISTS `sys_user_role`;
DROP TABLE IF EXISTS `sys_menu`;
DROP TABLE IF EXISTS `sys_role_menu`;
DROP TABLE IF EXISTS `sys_dict_type`;
DROP TABLE IF EXISTS `sys_dict_data`;
DROP TABLE IF EXISTS `sys_file`;
DROP TABLE IF EXISTS `sys_notice`;
DROP TABLE IF EXISTS `sys_message`;
DROP TABLE IF EXISTS `sys_oper_log`;

-- course 课程
CREATE TABLE `course` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `course_no` varchar(24) NOT NULL DEFAULT '' COMMENT '课程编号 KC+学期码+3位序号',
  `course_name` varchar(60) NOT NULL DEFAULT '' COMMENT '课程名称 如Java程序设计',
  `semester` varchar(20) NOT NULL DEFAULT '' COMMENT '学期 如2026学年第一学期',
  `college_name` varchar(50) NOT NULL DEFAULT '' COMMENT '开课学院',
  `teacher_id` bigint NULL DEFAULT NULL COMMENT '授课教师 sys_user.id',
  `class_name` varchar(50) NULL DEFAULT NULL COMMENT '教学班 如软工2301',
  `student_count` int NOT NULL DEFAULT '0' COMMENT '学生人数（由选课名单汇总）',
  `language_type` varchar(20) NOT NULL DEFAULT '' COMMENT '编程语言 Java/Python/C++/C/JavaScript/Go',
  `assignment_count` int NOT NULL DEFAULT '0' COMMENT '作业数量（由作业表汇总）',
  `cover_image` varchar(200) NOT NULL DEFAULT '' COMMENT '课程封面相对路径',
  `status` varchar(20) NULL DEFAULT NULL COMMENT '状态 进行中/已结课/已归档',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除 0 否 1 是',
  `create_by` bigint NULL DEFAULT NULL COMMENT '创建人',
  `update_by` bigint NULL DEFAULT NULL COMMENT '最后修改人',
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本号',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_course_course_no` (`course_no`),
  KEY `idx_course_semester` (`semester`),
  KEY `idx_course_teacher_id` (`teacher_id`),
  KEY `idx_course_language_type` (`language_type`),
  KEY `idx_course_status` (`status`),
  KEY `idx_course_teacher_id_semester` (`teacher_id`,`semester`),
  KEY `idx_course_language_type_status` (`language_type`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='课程';

-- code_assignment 编程作业
CREATE TABLE `code_assignment` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `assignment_no` varchar(32) NOT NULL DEFAULT '' COMMENT '作业编号 ZY+yyMMdd+3位序号',
  `course_id` bigint NULL DEFAULT NULL COMMENT '所属课程 course.id',
  `title` varchar(100) NULL DEFAULT NULL COMMENT '标题 同课程同周次不可重复',
  `description` text NOT NULL COMMENT '题目描述 不少于30字，含输入输出说明',
  `language_type` varchar(20) NOT NULL DEFAULT '' COMMENT '编程语言',
  `publish_time` datetime NULL DEFAULT NULL COMMENT '发布时间 草稿为空',
  `deadline` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '截止时间 必须晚于发布时间',
  `late_deadline` datetime NULL DEFAULT NULL COMMENT '迟交截止 最多晚于截止7天',
  `review_deadline` datetime NULL DEFAULT NULL COMMENT '互评截止时间（补充字段，互评任务默认取此值）',
  `test_case_count` int NOT NULL DEFAULT '0' COMMENT '用例数量 1-30',
  `peer_review_count` int NOT NULL DEFAULT '0' COMMENT '互评份数 0表示不互评 1-5',
  `weight` decimal(5,2) NOT NULL DEFAULT '0' COMMENT '成绩权重 0.00-100.00',
  `run_weight` int NOT NULL DEFAULT '0' COMMENT '运行结果分权重 三项合计必须100',
  `peer_weight` int NOT NULL DEFAULT '0' COMMENT '互评分权重 三项合计必须100',
  `teacher_weight` int NOT NULL DEFAULT '0' COMMENT '教师评分权重 三项合计必须100',
  `status` varchar(20) NULL DEFAULT NULL COMMENT '状态 草稿/已发布/提交中/互评中/评分中/已归档/已撤回',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除 0 否 1 是',
  `create_by` bigint NULL DEFAULT NULL COMMENT '创建人',
  `update_by` bigint NULL DEFAULT NULL COMMENT '最后修改人',
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本号',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_code_assignment_assignment_no` (`assignment_no`),
  KEY `idx_code_assignment_course_id` (`course_id`),
  KEY `idx_code_assignment_language_type` (`language_type`),
  KEY `idx_code_assignment_deadline` (`deadline`),
  KEY `idx_code_assignment_status` (`status`),
  KEY `idx_code_assignment_course_id_deadline` (`course_id`,`deadline`),
  KEY `idx_code_assignment_status_publish_time` (`status`,`publish_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='编程作业';

-- code_submission 代码提交
CREATE TABLE `code_submission` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `submit_no` varchar(32) NOT NULL DEFAULT '' COMMENT '提交编号 TD+yyMMdd+5位序号',
  `assignment_id` bigint NULL DEFAULT NULL COMMENT '作业 code_assignment.id',
  `student_id` bigint NULL DEFAULT NULL COMMENT '学生 sys_user.id',
  `file_path` varchar(255) NULL DEFAULT NULL COMMENT '源文件相对路径 禁止外链',
  `file_size` int NULL DEFAULT NULL COMMENT '源文件大小（字节）≤204800',
  `code_text` mediumtext NOT NULL COMMENT '代码正文快照（≤64KB，互评展示与版本对比用）',
  `code_language` varchar(20) NOT NULL DEFAULT '' COMMENT '提交时的语言快照',
  `code_lines` int NOT NULL DEFAULT '0' COMMENT '代码行数 1-2000',
  `code_digest` varchar(64) NOT NULL DEFAULT '' COMMENT '代码指纹（归一化后 SHA-1，相似度比对用）',
  `submit_time` datetime NULL DEFAULT NULL COMMENT '提交时间 以服务器时间为准',
  `submit_count` tinyint NOT NULL DEFAULT '0' COMMENT '提交次数 1-20',
  `compile_result` varchar(20) NOT NULL DEFAULT '' COMMENT '编译结果 未运行/通过/编译失败',
  `pass_count` int NOT NULL DEFAULT '0' COMMENT '用例通过数 0-作业用例数',
  `total_count` int NOT NULL DEFAULT '0' COMMENT '用例总数（提交时快照）',
  `error_summary` varchar(300) NULL DEFAULT NULL COMMENT '编译错误摘要（编译失败必填）',
  `is_late` tinyint NOT NULL DEFAULT '0' COMMENT '是否迟交 0按时 1迟交',
  `status` varchar(20) NULL DEFAULT NULL COMMENT '状态 待登记/已登记/已进入互评/已评分',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除 0 否 1 是',
  `create_by` bigint NULL DEFAULT NULL COMMENT '创建人',
  `update_by` bigint NULL DEFAULT NULL COMMENT '最后修改人',
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本号',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_code_submission_submit_no` (`submit_no`),
  KEY `idx_code_submission_assignment_id` (`assignment_id`),
  KEY `idx_code_submission_student_id` (`student_id`),
  KEY `idx_code_submission_code_digest` (`code_digest`),
  KEY `idx_code_submission_submit_time` (`submit_time`),
  KEY `idx_code_submission_compile_result` (`compile_result`),
  KEY `idx_code_submission_status` (`status`),
  KEY `idx_code_submission_assignment_id_student_id` (`assignment_id`,`student_id`),
  KEY `idx_code_submission_status_submit_time` (`status`,`submit_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='代码提交';

-- code_submission_version 提交版本
CREATE TABLE `code_submission_version` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `version_no` varchar(32) NOT NULL DEFAULT '' COMMENT '版本编号 BB+提交编号+2位序号',
  `submission_id` bigint NULL DEFAULT NULL COMMENT '提交 code_submission.id',
  `assignment_id` bigint NULL DEFAULT NULL COMMENT '作业 code_assignment.id',
  `student_id` bigint NULL DEFAULT NULL COMMENT '学生 sys_user.id',
  `seq_no` int NOT NULL DEFAULT '0' COMMENT '第几次提交 1 起',
  `code_language` varchar(20) NOT NULL DEFAULT '' COMMENT '语言快照',
  `code_lines` int NOT NULL DEFAULT '0' COMMENT '代码行数',
  `file_size` int NULL DEFAULT NULL COMMENT '文件大小（字节）',
  `code_digest` varchar(64) NOT NULL DEFAULT '' COMMENT '归一化后指纹',
  `code_text` mediumtext NOT NULL COMMENT '该版本代码正文',
  `is_late` tinyint NOT NULL DEFAULT '0' COMMENT '是否迟交',
  `submit_time` datetime NULL DEFAULT NULL COMMENT '提交时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除 0 否 1 是',
  `create_by` bigint NULL DEFAULT NULL COMMENT '创建人',
  `update_by` bigint NULL DEFAULT NULL COMMENT '最后修改人',
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本号',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_code_submission_version_version_no` (`version_no`),
  KEY `idx_code_submission_version_submission_id` (`submission_id`),
  KEY `idx_code_submission_version_assignment_id` (`assignment_id`),
  KEY `idx_code_submission_version_student_id` (`student_id`),
  KEY `idx_code_submission_version_submit_time` (`submit_time`),
  KEY `idx_code_submission_version_submission_id_seq_no` (`submission_id`,`seq_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='提交版本';

-- peer_review_task 互评任务
CREATE TABLE `peer_review_task` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `task_no` varchar(32) NOT NULL DEFAULT '' COMMENT '任务编号 HP+yyMMdd+5位序号',
  `assignment_id` bigint NULL DEFAULT NULL COMMENT '作业 code_assignment.id',
  `reviewer_id` bigint NULL DEFAULT NULL COMMENT '评阅人 sys_user.id，不能等于被评提交作者',
  `submission_id` bigint NULL DEFAULT NULL COMMENT '被评提交 code_submission.id',
  `assign_round` tinyint NOT NULL DEFAULT '0' COMMENT '分配轮次 1首次 2补评 3重新互评',
  `deadline` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '截止时间',
  `is_anonymous` tinyint NOT NULL DEFAULT '0' COMMENT '是否匿名 1匿名 0实名',
  `finish_time` datetime NULL DEFAULT NULL COMMENT '完成时间',
  `remind_count` tinyint NOT NULL DEFAULT '0' COMMENT '提醒次数（截止前2小时催评）',
  `status` varchar(20) NULL DEFAULT NULL COMMENT '状态 待评/已评/超时未评/已豁免',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除 0 否 1 是',
  `create_by` bigint NULL DEFAULT NULL COMMENT '创建人',
  `update_by` bigint NULL DEFAULT NULL COMMENT '最后修改人',
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本号',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_peer_review_task_task_no` (`task_no`),
  KEY `idx_peer_review_task_assignment_id` (`assignment_id`),
  KEY `idx_peer_review_task_reviewer_id` (`reviewer_id`),
  KEY `idx_peer_review_task_submission_id` (`submission_id`),
  KEY `idx_peer_review_task_status` (`status`),
  KEY `idx_peer_review_task_reviewer_id_status` (`reviewer_id`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='互评任务';

-- peer_review_score 互评评分
CREATE TABLE `peer_review_score` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `task_id` bigint NULL DEFAULT NULL COMMENT '互评任务 peer_review_task.id（一任务一条）',
  `reviewer_id` bigint NULL DEFAULT NULL COMMENT '评阅人 sys_user.id',
  `submission_id` bigint NULL DEFAULT NULL COMMENT '被评提交 code_submission.id',
  `correctness_score` decimal(5,1) NOT NULL DEFAULT '0' COMMENT '正确性得分 0.0-60.0',
  `readability_score` decimal(5,1) NOT NULL DEFAULT '0' COMMENT '可读性得分 0.0-25.0',
  `style_score` decimal(5,1) NOT NULL DEFAULT '0' COMMENT '规范得分 0.0-15.0',
  `total_score` decimal(5,1) NULL DEFAULT NULL COMMENT '互评总分 三项之和 0.0-100.0',
  `comment` varchar(1000) NULL DEFAULT NULL COMMENT '评语 不少于20字，需指出具体代码位置',
  `comment_length` int NULL DEFAULT NULL COMMENT '评语字数（去空白）',
  `low_quality` tinyint NOT NULL DEFAULT '0' COMMENT '是否低质量 1套话或字数不足',
  `submit_time` datetime NULL DEFAULT NULL COMMENT '提交时间',
  `status` varchar(20) NULL DEFAULT NULL COMMENT '状态 草稿/已提交/已隐藏',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除 0 否 1 是',
  `create_by` bigint NULL DEFAULT NULL COMMENT '创建人',
  `update_by` bigint NULL DEFAULT NULL COMMENT '最后修改人',
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本号',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_peer_review_score_task_id` (`task_id`),
  KEY `idx_peer_review_score_reviewer_id` (`reviewer_id`),
  KEY `idx_peer_review_score_submission_id` (`submission_id`),
  KEY `idx_peer_review_score_total_score` (`total_score`),
  KEY `idx_peer_review_score_low_quality` (`low_quality`),
  KEY `idx_peer_review_score_reviewer_id_submit_time` (`reviewer_id`,`submit_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='互评评分';

-- similarity_record 查重记录
CREATE TABLE `similarity_record` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `record_no` varchar(32) NOT NULL DEFAULT '' COMMENT '记录编号 CD+yyMMdd+4位序号',
  `assignment_id` bigint NULL DEFAULT NULL COMMENT '作业 code_assignment.id',
  `submission_a_id` bigint NULL DEFAULT NULL COMMENT '提交A（取较小ID）',
  `submission_b_id` bigint NULL DEFAULT NULL COMMENT '提交B（取较大ID）',
  `similarity_rate` decimal(5,2) NOT NULL DEFAULT '0' COMMENT '相似度 0.00-100.00，>70 进入待复核',
  `structure_rate` decimal(5,2) NOT NULL DEFAULT '0' COMMENT '结构相似度（权重0.5）',
  `identifier_rate` decimal(5,2) NOT NULL DEFAULT '0' COMMENT '标识符相似度（权重0.3）',
  `comment_rate` decimal(5,2) NOT NULL DEFAULT '0' COMMENT '注释相似度（权重0.2）',
  `match_type` varchar(30) NOT NULL DEFAULT '' COMMENT '命中类型 变量重命名/结构一致/注释雷同/完全一致',
  `evidence_snippet` varchar(1000) NOT NULL DEFAULT '' COMMENT '证据片段 相同行区间与内容摘要',
  `evidence_image` varchar(200) NULL DEFAULT NULL COMMENT '证据截图相对路径',
  `check_rule_version` varchar(20) NOT NULL DEFAULT '' COMMENT '检测规则版本 v1.2',
  `batch_no` varchar(32) NOT NULL DEFAULT '' COMMENT '检测批次号（重复检测覆盖旧记录时保留）',
  `review_result` varchar(20) NOT NULL DEFAULT '' COMMENT '复核结论 待复核/确认抄袭/误报/需面谈',
  `reviewer_id` bigint NULL DEFAULT NULL COMMENT '复核人 sys_user.id',
  `second_reviewer_id` bigint NULL DEFAULT NULL COMMENT '第二名签字教师（确认抄袭必需）',
  `review_remark` varchar(300) NULL DEFAULT NULL COMMENT '复核理由',
  `review_time` datetime NULL DEFAULT NULL COMMENT '复核时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除 0 否 1 是',
  `create_by` bigint NULL DEFAULT NULL COMMENT '创建人',
  `update_by` bigint NULL DEFAULT NULL COMMENT '最后修改人',
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本号',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_similarity_record_record_no` (`record_no`),
  KEY `idx_similarity_record_assignment_id` (`assignment_id`),
  KEY `idx_similarity_record_submission_a_id` (`submission_a_id`),
  KEY `idx_similarity_record_submission_b_id` (`submission_b_id`),
  KEY `idx_similarity_record_similarity_rate` (`similarity_rate`),
  KEY `idx_similarity_record_batch_no` (`batch_no`),
  KEY `idx_similarity_record_review_result` (`review_result`),
  KEY `idx_similarity_record_assignment_id_submission_a_id_submissi` (`assignment_id`,`submission_a_id`,`submission_b_id`),
  KEY `idx_similarity_record_review_result_similarity_rate` (`review_result`,`similarity_rate`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='查重记录';

-- score_summary 成绩汇总
CREATE TABLE `score_summary` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `assignment_id` bigint NULL DEFAULT NULL COMMENT '作业 code_assignment.id',
  `student_id` bigint NULL DEFAULT NULL COMMENT '学生 sys_user.id',
  `auto_score` decimal(5,1) NOT NULL DEFAULT '0' COMMENT '运行结果分 = 通过数/总数*100',
  `peer_score` decimal(5,1) NOT NULL DEFAULT '0' COMMENT '互评分（按可信度加权后）',
  `peer_raw_score` decimal(5,1) NOT NULL DEFAULT '0' COMMENT '互评原始均分（未折算，便于复核）',
  `teacher_score` decimal(5,1) NULL DEFAULT NULL COMMENT '教师评分 0.0-100.0 可空',
  `final_score` decimal(5,1) NOT NULL DEFAULT '0' COMMENT '最终成绩 三项按权重合成',
  `class_rank` int NOT NULL DEFAULT '0' COMMENT '班级排名',
  `credibility_score` decimal(5,1) NOT NULL DEFAULT '0' COMMENT '互评可信度分',
  `credibility_grade` varchar(20) NOT NULL DEFAULT '' COMMENT '可信度等级 高可信/中可信/较低可信/低可信',
  `adjust_reason` varchar(300) NULL DEFAULT NULL COMMENT '人工调整说明（≥10字）',
  `publish_status` varchar(20) NOT NULL DEFAULT '' COMMENT '发布状态 未发布/已发布/已撤回',
  `publish_time` datetime NULL DEFAULT NULL COMMENT '发布时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除 0 否 1 是',
  `create_by` bigint NULL DEFAULT NULL COMMENT '创建人',
  `update_by` bigint NULL DEFAULT NULL COMMENT '最后修改人',
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本号',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_score_summary_assignment_id_student_id` (`assignment_id`,`student_id`),
  KEY `idx_score_summary_assignment_id` (`assignment_id`),
  KEY `idx_score_summary_student_id` (`student_id`),
  KEY `idx_score_summary_final_score` (`final_score`),
  KEY `idx_score_summary_credibility_grade` (`credibility_grade`),
  KEY `idx_score_summary_publish_status` (`publish_status`),
  KEY `idx_score_summary_student_id_publish_status` (`student_id`,`publish_status`),
  KEY `idx_score_summary_assignment_id_final_score` (`assignment_id`,`final_score`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='成绩汇总';

-- appeal_record 成绩申诉
CREATE TABLE `appeal_record` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `appeal_no` varchar(32) NOT NULL DEFAULT '' COMMENT '申诉编号 SS+yyMMdd+4位序号',
  `score_id` bigint NULL DEFAULT NULL COMMENT '成绩记录 score_summary.id',
  `student_id` bigint NULL DEFAULT NULL COMMENT '学生 sys_user.id',
  `appeal_type` varchar(20) NOT NULL DEFAULT '' COMMENT '申诉类型 互评分偏低/查重误判/成绩计算错误',
  `reason` varchar(500) NOT NULL DEFAULT '' COMMENT '申诉理由 不少于20字',
  `expect_score` decimal(5,1) NULL DEFAULT NULL COMMENT '期望分数（可空）',
  `evidence_urls` varchar(1000) NULL DEFAULT NULL COMMENT '证据附件相对路径，最多5个',
  `status` varchar(20) NULL DEFAULT NULL COMMENT '处理状态 待受理/处理中/已驳回/已改分/需重新互评',
  `handler_id` bigint NULL DEFAULT NULL COMMENT '处理人 sys_user.id（不能是原评分教师）',
  `handle_result` varchar(500) NULL DEFAULT NULL COMMENT '处理结果 改分需写明新分数与依据',
  `handle_time` datetime NULL DEFAULT NULL COMMENT '处理时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除 0 否 1 是',
  `create_by` bigint NULL DEFAULT NULL COMMENT '创建人',
  `update_by` bigint NULL DEFAULT NULL COMMENT '最后修改人',
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本号',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_appeal_record_appeal_no` (`appeal_no`),
  KEY `idx_appeal_record_score_id` (`score_id`),
  KEY `idx_appeal_record_student_id` (`student_id`),
  KEY `idx_appeal_record_appeal_type` (`appeal_type`),
  KEY `idx_appeal_record_status` (`status`),
  KEY `idx_appeal_record_student_id_status` (`student_id`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='成绩申诉';

-- credibility_rule 可信度规则
CREATE TABLE `credibility_rule` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `rule_version` varchar(20) NULL DEFAULT NULL COMMENT '规则版本 v2.1',
  `rule_name` varchar(60) NOT NULL DEFAULT '' COMMENT '规则名称',
  `weight_deviation` decimal(5,2) NOT NULL DEFAULT '0' COMMENT '评分偏离度权重 %',
  `weight_comment` decimal(5,2) NOT NULL DEFAULT '0' COMMENT '评语有效长度权重 %',
  `weight_finish_rate` decimal(5,2) NOT NULL DEFAULT '0' COMMENT '互评完成率权重 %',
  `weight_similarity` decimal(5,2) NOT NULL DEFAULT '0' COMMENT '提交相似度权重 %',
  `weight_consistency` decimal(5,2) NOT NULL DEFAULT '0' COMMENT '评分一致性权重 %',
  `grade_high` decimal(5,1) NOT NULL DEFAULT '0' COMMENT '高可信阈值 默认85',
  `grade_mid` decimal(5,1) NOT NULL DEFAULT '0' COMMENT '中可信阈值 默认65',
  `grade_low` decimal(5,1) NOT NULL DEFAULT '0' COMMENT '较低可信阈值 默认45',
  `similarity_alert` decimal(5,2) NOT NULL DEFAULT '0' COMMENT '相似度告警线 % 默认70',
  `effect_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '生效时间',
  `operator_id` bigint NULL DEFAULT NULL COMMENT '修改人 sys_user.id',
  `status` varchar(20) NULL DEFAULT NULL COMMENT '状态 生效中/已失效',
  `remark` varchar(300) NULL DEFAULT NULL COMMENT '变更说明',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除 0 否 1 是',
  `create_by` bigint NULL DEFAULT NULL COMMENT '创建人',
  `update_by` bigint NULL DEFAULT NULL COMMENT '最后修改人',
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本号',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_credibility_rule_rule_version` (`rule_version`),
  KEY `idx_credibility_rule_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='可信度规则';

-- credibility_snapshot 可信度留痕
CREATE TABLE `credibility_snapshot` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `snapshot_no` varchar(32) NOT NULL DEFAULT '' COMMENT '快照编号 CT+yyMMdd+6位序号',
  `task_id` bigint NULL DEFAULT NULL COMMENT '互评任务 peer_review_task.id',
  `score_id` bigint NULL DEFAULT NULL COMMENT '互评评分 peer_review_score.id',
  `submission_id` bigint NULL DEFAULT NULL COMMENT '被评提交 code_submission.id',
  `student_id` bigint NULL DEFAULT NULL COMMENT '被评学生 sys_user.id',
  `assignment_id` bigint NULL DEFAULT NULL COMMENT '作业 code_assignment.id',
  `rule_version` varchar(20) NULL DEFAULT NULL COMMENT '计算所用规则版本',
  `s_deviation` decimal(5,1) NOT NULL DEFAULT '0' COMMENT '评分偏离度得分',
  `s_comment` decimal(5,1) NOT NULL DEFAULT '0' COMMENT '评语有效长度得分',
  `s_finish_rate` decimal(5,1) NOT NULL DEFAULT '0' COMMENT '互评完成率得分',
  `s_similarity` decimal(5,1) NOT NULL DEFAULT '0' COMMENT '提交相似度得分',
  `s_consistency` decimal(5,1) NULL DEFAULT NULL COMMENT '评分一致性得分',
  `total_score` decimal(5,1) NULL DEFAULT NULL COMMENT '可信度总分 Σ(得分×权重)',
  `grade` varchar(20) NULL DEFAULT NULL COMMENT '结果等级 高可信/中可信/较低可信/低可信',
  `input_json` text NULL DEFAULT NULL COMMENT '输入快照 JSON（计算时冻结）',
  `conclusion` varchar(300) NULL DEFAULT NULL COMMENT '结论说明（互评分如何计入成绩）',
  `manual_flag` tinyint NULL DEFAULT NULL COMMENT '是否人工修正 0否 1是',
  `manual_reason` varchar(200) NULL DEFAULT NULL COMMENT '人工修正原因（≥5字）',
  `calc_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '生成时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除 0 否 1 是',
  `create_by` bigint NULL DEFAULT NULL COMMENT '创建人',
  `update_by` bigint NULL DEFAULT NULL COMMENT '最后修改人',
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本号',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_credibility_snapshot_snapshot_no` (`snapshot_no`),
  KEY `idx_credibility_snapshot_task_id` (`task_id`),
  KEY `idx_credibility_snapshot_submission_id` (`submission_id`),
  KEY `idx_credibility_snapshot_student_id` (`student_id`),
  KEY `idx_credibility_snapshot_assignment_id` (`assignment_id`),
  KEY `idx_credibility_snapshot_rule_version` (`rule_version`),
  KEY `idx_credibility_snapshot_total_score` (`total_score`),
  KEY `idx_credibility_snapshot_grade` (`grade`),
  KEY `idx_credibility_snapshot_calc_time` (`calc_time`),
  KEY `idx_credibility_snapshot_submission_id_rule_version` (`submission_id`,`rule_version`),
  KEY `idx_credibility_snapshot_student_id_create_time` (`student_id`,`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='可信度留痕';

-- sys_user 用户
CREATE TABLE `sys_user` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `username` varchar(40) NULL DEFAULT NULL COMMENT '登录账号 / 学号',
  `password` varchar(100) NULL DEFAULT NULL COMMENT 'BCrypt 密码',
  `real_name` varchar(40) NULL DEFAULT NULL COMMENT '姓名',
  `student_no` varchar(20) NULL DEFAULT NULL COMMENT '学号（学生角色）',
  `phone` varchar(20) NULL DEFAULT NULL COMMENT '手机号',
  `email` varchar(60) NULL DEFAULT NULL COMMENT '邮箱',
  `avatar` varchar(200) NOT NULL DEFAULT '' COMMENT '头像相对路径',
  `dept_id` bigint NULL DEFAULT NULL COMMENT '所属学院/部门 sys_org.id',
  `role_id` bigint NULL DEFAULT NULL COMMENT '主角色 sys_role.id（菜单与数据范围据此取）',
  `class_name` varchar(50) NULL DEFAULT NULL COMMENT '班级',
  `title` varchar(40) NULL DEFAULT NULL COMMENT '职称 / 年级',
  `credit_score` decimal(5,1) NULL DEFAULT NULL COMMENT '互评信用分',
  `fail_count` int NOT NULL DEFAULT '0' COMMENT '连续登录失败次数',
  `lock_time` datetime NULL DEFAULT NULL COMMENT '锁定截止时间，为空表示未锁定',
  `last_login_time` datetime NULL DEFAULT NULL COMMENT '最近登录时间',
  `status` tinyint NULL DEFAULT NULL COMMENT '状态 1正常 0停用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_sys_user_username` (`username`),
  KEY `idx_sys_user_student_no` (`student_no`),
  KEY `idx_sys_user_dept_id` (`dept_id`),
  KEY `idx_sys_user_role_id` (`role_id`),
  KEY `idx_sys_user_status` (`status`),
  KEY `idx_sys_user_dept_id_status` (`dept_id`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='用户';

-- sys_org 组织
CREATE TABLE `sys_org` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `org_name` varchar(50) NOT NULL DEFAULT '' COMMENT '组织名称 如计算机学院',
  `org_code` varchar(30) NOT NULL DEFAULT '' COMMENT '组织编码',
  `parent_id` bigint NULL DEFAULT NULL COMMENT '上级组织',
  `org_type` varchar(20) NOT NULL DEFAULT '' COMMENT '类型 学院/系/教务处',
  `leader` varchar(40) NOT NULL DEFAULT '' COMMENT '负责人',
  `phone` varchar(20) NULL DEFAULT NULL COMMENT '联系电话',
  `sort_no` int NULL DEFAULT NULL COMMENT '排序',
  `status` tinyint NULL DEFAULT NULL COMMENT '状态 1正常 0停用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_sys_org_org_name` (`org_name`),
  KEY `idx_sys_org_parent_id` (`parent_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='组织';

-- sys_role 角色
CREATE TABLE `sys_role` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `role_name` varchar(40) NULL DEFAULT NULL COMMENT '角色名称',
  `role_code` varchar(30) NULL DEFAULT NULL COMMENT '角色编码 TEACHER/TA/STUDENT/ACADEMIC/ADMIN',
  `data_scope` varchar(20) NULL DEFAULT NULL COMMENT '数据范围 ALL/DEPT/SELF',
  `sort_no` int NULL DEFAULT NULL COMMENT '排序',
  `remark` varchar(200) NULL DEFAULT NULL COMMENT '说明',
  `status` tinyint NULL DEFAULT NULL COMMENT '状态 1正常 0停用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_sys_role_role_code` (`role_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='角色';

-- sys_user_role 用户角色
CREATE TABLE `sys_user_role` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `user_id` bigint NOT NULL DEFAULT '0' COMMENT '用户 sys_user.id',
  `role_id` bigint NULL DEFAULT NULL COMMENT '角色 sys_role.id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  KEY `idx_sys_user_role_user_id` (`user_id`),
  KEY `idx_sys_user_role_role_id` (`role_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='用户角色';

-- sys_menu 菜单
CREATE TABLE `sys_menu` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `parent_id` bigint NULL DEFAULT NULL COMMENT '上级菜单 0为根',
  `menu_name` varchar(50) NULL DEFAULT NULL COMMENT '菜单名称',
  `menu_type` varchar(10) NULL DEFAULT NULL COMMENT '类型 DIR目录/MENU菜单/BTN按钮',
  `path` varchar(120) NULL DEFAULT NULL COMMENT '路由地址',
  `component` varchar(120) NULL DEFAULT NULL COMMENT '组件路径',
  `perms` varchar(100) NULL DEFAULT NULL COMMENT '权限标识',
  `icon` varchar(40) NULL DEFAULT NULL COMMENT '图标',
  `sort_no` int NULL DEFAULT NULL COMMENT '排序',
  `visible` tinyint NULL DEFAULT NULL COMMENT '是否可见 1是 0否',
  `status` tinyint NULL DEFAULT NULL COMMENT '状态 1正常 0停用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  KEY `idx_sys_menu_parent_id` (`parent_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='菜单';

-- sys_role_menu 角色菜单
CREATE TABLE `sys_role_menu` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `role_id` bigint NULL DEFAULT NULL COMMENT '角色 sys_role.id',
  `menu_id` bigint NOT NULL DEFAULT '0' COMMENT '菜单 sys_menu.id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  KEY `idx_sys_role_menu_role_id` (`role_id`),
  KEY `idx_sys_role_menu_menu_id` (`menu_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='角色菜单';

-- sys_dict_type 字典类型
CREATE TABLE `sys_dict_type` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `dict_name` varchar(60) NULL DEFAULT NULL COMMENT '字典名称',
  `dict_type` varchar(60) NOT NULL DEFAULT '' COMMENT '字典类型编码',
  `remark` varchar(200) NULL DEFAULT NULL COMMENT '说明',
  `status` tinyint NULL DEFAULT NULL COMMENT '状态 1正常 0停用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_sys_dict_type_dict_type` (`dict_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='字典类型';

-- sys_dict_data 字典数据
CREATE TABLE `sys_dict_data` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `dict_type` varchar(60) NOT NULL DEFAULT '' COMMENT '字典类型编码',
  `dict_label` varchar(60) NULL DEFAULT NULL COMMENT '字典标签',
  `dict_value` varchar(60) NULL DEFAULT NULL COMMENT '字典值',
  `tag_class` varchar(20) NOT NULL DEFAULT '' COMMENT '前端标签样式 t-green/t-blue…',
  `sort_no` int NULL DEFAULT NULL COMMENT '排序',
  `status` tinyint NULL DEFAULT NULL COMMENT '状态 1正常 0停用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  KEY `idx_sys_dict_data_dict_type` (`dict_type`),
  KEY `idx_sys_dict_data_sort_no` (`sort_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='字典数据';

-- sys_file 文件
CREATE TABLE `sys_file` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `file_name` varchar(120) NULL DEFAULT NULL COMMENT '文件名',
  `file_path` varchar(200) NULL DEFAULT NULL COMMENT '相对路径',
  `file_size` bigint NULL DEFAULT NULL COMMENT '字节数',
  `file_type` varchar(20) NULL DEFAULT NULL COMMENT '扩展名',
  `biz_type` varchar(30) NULL DEFAULT NULL COMMENT '业务类型 seed/avatar/code/evidence',
  `biz_id` bigint NULL DEFAULT NULL COMMENT '业务主键',
  `uploader_id` bigint NULL DEFAULT NULL COMMENT '上传人 sys_user.id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  KEY `idx_sys_file_biz_type` (`biz_type`),
  KEY `idx_sys_file_biz_id` (`biz_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='文件';

-- sys_notice 公告
CREATE TABLE `sys_notice` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `title` varchar(120) NULL DEFAULT NULL COMMENT '标题',
  `content` text NULL DEFAULT NULL COMMENT '正文',
  `notice_type` varchar(20) NULL DEFAULT NULL COMMENT '类型 通知/公告/规则',
  `publish_time` datetime NULL DEFAULT NULL COMMENT '发布时间',
  `publisher_id` bigint NULL DEFAULT NULL COMMENT '发布人',
  `status` varchar(20) NULL DEFAULT NULL COMMENT '状态 草稿/已发布/已下线',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  KEY `idx_sys_notice_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='公告';

-- sys_message 站内消息
CREATE TABLE `sys_message` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `receiver_id` bigint NULL DEFAULT NULL COMMENT '接收人 sys_user.id',
  `title` varchar(120) NULL DEFAULT NULL COMMENT '标题',
  `content` varchar(500) NULL DEFAULT NULL COMMENT '内容',
  `msg_type` varchar(20) NULL DEFAULT NULL COMMENT '类型 待办/作业/查重/成绩/申诉',
  `biz_type` varchar(30) NULL DEFAULT NULL COMMENT '业务类型 assignment/review/appeal',
  `biz_id` bigint NULL DEFAULT NULL COMMENT '业务主键',
  `link_url` varchar(160) NULL DEFAULT NULL COMMENT '跳转路径',
  `read_flag` tinyint NULL DEFAULT NULL COMMENT '是否已读 0未读 1已读',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  KEY `idx_sys_message_receiver_id` (`receiver_id`),
  KEY `idx_sys_message_msg_type` (`msg_type`),
  KEY `idx_sys_message_read_flag` (`read_flag`),
  KEY `idx_sys_message_receiver_id_read_flag` (`receiver_id`,`read_flag`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='站内消息';

-- sys_oper_log 操作日志
CREATE TABLE `sys_oper_log` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `module` varchar(40) NOT NULL DEFAULT '' COMMENT '模块',
  `oper_type` varchar(30) NOT NULL DEFAULT '' COMMENT '操作类型 新增/修改/发布/重算',
  `biz_no` varchar(40) NULL DEFAULT NULL COMMENT '业务编号',
  `content` varchar(500) NULL DEFAULT NULL COMMENT '内容摘要',
  `oper_id` bigint NULL DEFAULT NULL COMMENT '操作人 sys_user.id',
  `oper_name` varchar(40) NULL DEFAULT NULL COMMENT '操作人姓名',
  `oper_time` datetime NULL DEFAULT NULL COMMENT '操作时间',
  `ip` varchar(40) NULL DEFAULT NULL COMMENT 'IP',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  KEY `idx_sys_oper_log_biz_no` (`biz_no`),
  KEY `idx_sys_oper_log_oper_id` (`oper_id`),
  KEY `idx_sys_oper_log_oper_time` (`oper_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='操作日志';

