INSERT INTO `sys_notice` (`id`,`title`,`content`,`notice_type`,`publish_time`,`publisher_id`,`status`,`create_time`,`update_time`,`deleted`) VALUES
(NULL,'关于开展本学期编程作业互评工作的通知','本学期全部编程课程作业采用同伴互评方式，每份提交由 2 至 3 名同学匿名评阅。互评评分需指出具体代码位置，评语少于20字将判定为低质量并被系统标记。','教学通知','2026-10-13 10:00:00',2,1,'2026-10-13 10:00:00','2026-10-13 10:00:00',0),
(NULL,'互评可信度规则升级说明（v2.1）','自本月起互评可信度按评分偏离度25%、评语有效长度20%、互评完成率20%、提交相似度20%、评分一致性15%计算。高可信互评直接计入成绩，中可信按0.8系数折算。','规则变更','2026-10-16 10:00:00',2,1,'2026-10-16 10:00:00','2026-10-16 10:00:00',0),
(NULL,'关于代码相似度检测的说明','系统按结构相似度0.5、标识符相似度0.3、注释相似度0.2合成相似度总分，超过70进入待复核。确认抄袭需两名教师签字，学生可在3个工作日内提出申诉。','学术规范','2026-10-19 10:00:00',2,1,'2026-10-19 10:00:00','2026-10-19 10:00:00',0),
(NULL,'成绩发布与申诉受理时限','成绩发布后 7 天内可发起申诉，逾期不再受理。申诉由非原评分教师受理，改分必须写明新分数与依据，处理结果同步推送站内消息。','成绩管理','2026-10-22 10:00:00',2,1,'2026-10-22 10:00:00','2026-10-22 10:00:00',0),
(NULL,'迟交提交处理办法','截止时间后 7 天内仍可提交，标记为迟交并按每次扣减 5 分处理；超过迟交窗口不再接受提交，需通过教师线下补交。','教学通知','2026-10-25 10:00:00',2,1,'2026-10-25 10:00:00','2026-10-25 10:00:00',0);
