INSERT INTO `code_assignment` (`id`,`assignment_no`,`course_id`,`title`,`description`,`language_type`,`publish_time`,`deadline`,`late_deadline`,`review_deadline`,`test_case_count`,`peer_review_count`,`weight`,`run_weight`,`peer_weight`,`teacher_weight`,`status`,`create_time`,`update_time`,`deleted`,`create_by`,`update_by`,`version`) VALUES
(1,'ZY260617001',1,'第1次作业：变量、运算符与控制流程','【题目说明】本次作业围绕变量、运算符与控制流程的核心知识点展开。
【输入说明】程序从标准输入读取数据，第一行为测试组数 n，随后 n 组数据。
【输出说明】每组数据输出一行结果，与样例完全一致的格式。
【提交要求】提交单个源文件，命名与学号一致，不得引用第三方未授权库。','Java','2026-06-17 08:00:00','2026-06-24 23:59:00','2026-07-01 23:59:00','2026-07-01 23:59:00',8,2,10.0,20,20,60,'已归档','2026-06-15 09:00:00','2026-06-24 09:00:00',0,NULL,NULL,0),
(2,'ZY260717002',1,'第2次作业：面向对象与集合框架','【题目说明】本次作业围绕面向对象与集合框架的核心知识点展开。
