-- ---------- 回填汇总字段 ----------
UPDATE `course` c SET assignment_count = (SELECT COUNT(*) FROM `code_assignment` a WHERE a.course_id = c.id AND a.status <> '草稿');
UPDATE `code_assignment` a SET peer_review_count = IF(peer_review_count = 0, 2, peer_review_count);


-- ---------- 数据修订（verify 阶段发现，幂等可重放） ----------
-- 需求 5.7：超过 70% 才生成待复核记录，故待复核队列里不允许出现低于阈值的记录；
-- 第 9 节要求「统计总数与明细总数一致」，看板「相似度告警数」= 本队列条数。
UPDATE `similarity_record` SET review_result='误报',
  review_remark='相似度低于告警阈值 70%，复核判定为误报，不进入抄袭处置',
  review_time = DATE_ADD(create_time, INTERVAL 6 HOUR)
WHERE review_result='待复核' AND similarity_rate < 70;
-- 补 3 条超阈值记录回队列，保证复核台有可操作数据（仅首次导入时生效）
UPDATE `similarity_record` SET review_result='待复核', review_remark='', review_time=NULL, reviewer_id=NULL
WHERE review_result='误报' AND similarity_rate >= 75 ORDER BY similarity_rate DESC LIMIT 3;
